                for (size_t j = 0; j < 3; j++)
                    propagated->m[i][j] = 0.0;
        }
        return ADCS_E_NULL;
    }

    if (!isfinite(dt_s) || dt_s < 0.0 || !isfinite(process_noise_rad2_s) || process_noise_rad2_s < 0.0) {
        for (size_t i = 0; i < 3; i++)
            for (size_t j = 0; j < 3; j++)
                propagated->m[i][j] = 0.0;
        return ADCS_E_RANGE;
    }

    if (!adcs_is_finite_vec3(body_rate_rad_s)) {
        for (size_t i = 0; i < 3; i++)
            for (size_t j = 0; j < 3; j++)
                propagated->m[i][j] = 0.0;
        return ADCS_E_RANGE;
    }

    adcs_mat3_t F = adcs_mat3_identity();

    double dt = dt_s;
    double wx = body_rate_rad_s->x;
    double wy = body_rate_rad_s->y;
    double wz = body_rate_rad_s->z;

    // F = I - dt * [omega]_x
    // Skew matrix [omega]_x based on normative map:
    // [ 0   -wz   wy ]
    // [ wz   0   -wx ]
    // [-wy   wx   0  ]

    F.m[0][1] = dt * wz;      // 0 - dt*(-wz)
    F.m[0][2] = -dt * wy;     // 0 - dt*(wy)
    F.m[1][0] = -dt * wz;     // 0 - dt*(wz)
    F.m[1][2] = dt * wx;      // 0 - dt*(-wx)
    F.m[2][0] = dt * wy;      // 0 - dt*(-wy)
    F.m[2][1] = -dt * wx;     // 0 - dt*(wx)

    adcs_mat3_t FT = adcs_mat3_transpose(&F);
    adcs_mat3_t FP = adcs_mat3_mul(&F, covariance);
    adcs_mat3_t P_next = adcs_mat3_mul(&FP, &FT);

    // Add process noise to diagonal only: P_next += process_noise * dt * I
    double noise_term = process_noise_rad2_s * dt_s;
    P_next.m[0][0] += noise_term;
    P_next.m[1][1] += noise_term;
    P_next.m[2][2] += noise_term;

    *propagated = P_next;
    return ADCS_OK;
}

